/// One `GenData.from_gen(3).moves` row, as `Move` reads it.
pub struct MoveRow {
    pub id: &'static str,
    pub pp: u16,
    pub target: &'static str,
    /// `"mustpressure" in flags` — the second half of `_pressure_on`.
    pub must_pressure: bool,
    pub base_power: u16,
    /// `Move.type` as a `PokemonType` NAME.
    pub typ: &'static str,
    /// `Move.should_be_stored(id, 3)`.
    pub storable: bool,
    /// `id in _PROTECT_COUNTER_MOVES` — `Move.is_protect_counter`.
    pub protect_counter: bool,
    /// `category in ("Physical", "Special")` — the `|move|` handler's pending
    /// damaging-move capture, which looks the target up (a creation side effect).
    pub damaging: bool,
}

